0].text,         formattedTexts[230].size,         formattedTexts[230].style,         formattedTexts[230].color     ) }   /* Helper function to create a formatted SpannableString */ fun createFormattedString(text: String, size: Int, style: Int, color: Int): SpannableString {     val spannableString = SpannableString(text)     val exExFlag = Spanned.SPAN_EXCLUSIVE_EXCLUSIVE     val start = 0      spannableString.setSpan(AbsoluteSizeSpan(size, true), start, spannableString.length, exExFlag)     spannableString.setSpan(StyleSpan(style), start, spannableString.length, exExFlag)     spannableString.setSpan(ForegroundColorSpan(color), start, spannableString.length, exExFlag)      return spannableString }
